<style>
.sn-page{font-family:Inter, sans-serif;color:#25313C}.sn-head{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;margin:0 0 22px}.sn-head h1{font-size:23px;font-weight:700;color:#123B5D;margin:0 0 6px}.sn-sub{font-size:13px;color:#64748B}.sn-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.sn-btn{display:inline-flex;align-items:center;justify-content:center;min-height:40px;padding:0 16px;border:1px solid #CBD5E1;border-radius:9px;background:#fff;color:#123B5D;text-decoration:none;font-size:13px;font-weight:600;cursor:pointer}.sn-primary{background:#123B5D;border-color:#123B5D;color:#fff}.sn-danger{color:#DC2626}.sn-panel{background:#fff;border:1px solid #CBD5E1;border-radius:15px;padding:20px;margin-bottom:18px}.sn-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.sn-kpi{background:#fff;border:1px solid #CBD5E1;border-radius:14px;padding:18px}.sn-kpi b{display:block;font-size:26px;color:#123B5D}.sn-kpi span,.sn-muted{font-size:12px;color:#64748B}.sn-table{width:100%;border-collapse:collapse}.sn-table th{background:#F8FAFC;color:#64748B;font-size:11px;text-align:left;padding:14px;font-weight:700}.sn-table td{padding:14px;border-top:1px solid #E2E8F0;font-size:13px}.sn-inline{display:flex;gap:8px;align-items:center;white-space:nowrap}.sn-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.sn-field label{display:block;font-size:12px;font-weight:600;margin-bottom:7px}.sn-field input,.sn-field select,.sn-field textarea{width:100%;border:1px solid #CBD5E1;border-radius:9px;padding:11px 12px;font:13px Inter,sans-serif;box-sizing:border-box}.sn-field textarea{min-height:100px}.sn-span{grid-column:1/-1}.sn-alert{padding:12px 15px;background:#F0FDF4;border:1px solid #BBF7D0;border-radius:9px;margin-bottom:16px;color:#166534}@media(max-width:800px){.sn-grid{grid-template-columns:repeat(2,1fr)}.sn-head{flex-direction:column}.sn-form{grid-template-columns:1fr}}
</style>